const cache = {};
function load(id) {
 if (cache[id]) return cache[id].exports;
 if (!modules[id]) throw Error('Missing multiplayer module: ' + id);
 const module = { exports: {} }; cache[id] = module;
 modules[id](module, module.exports, name => {
  if (name === 'crypto') return require('crypto');
  if (!name.startsWith('.')) throw Error('Unexpected multiplayer dependency: ' + name);
  const key = require('path').posix.normalize(require('path').posix.join(require('path').posix.dirname(id), name));
  return load(modules[key] ? key : key + '.js');
 });
 return module.exports;
}
